import{_ as r,l as o,o as a,c as s,v as l,p,x as i,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"无薄膜运行的风险","description":"","frontmatter":{"title":"无薄膜运行的风险","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pellicle-free-risk.md","filePath":"litho/pellicle-free-risk.md","lastUpdated":1789023840000}'),h={name:"litho/pellicle-free-risk.md"};function E(A,e,_,m,u,f){const t=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=l('<h1 id="无薄膜运行的风险" tabindex="-1">无薄膜运行的风险 <a class="header-anchor" href="#无薄膜运行的风险" aria-label="Permalink to &quot;无薄膜运行的风险&quot;">​</a></h1><div class="epigraph"><p>早期高功率或膜不可用时，有过无 pellicle 跑关键层。颗粒直接落在多层上，打印阈值就是缺陷规格，检测频率变成产能税。</p><footer>—— 对照 ASML 对 pellicle 导入前后策略的公开叙述；不要写成推荐工艺</footer></div><p><a href="/litho/pellicle-lifetime">上一课</a>把膜写成消耗品。缺口是膜还扛不住功率、或破膜率不可接受时：有人选择无薄膜运行。本课钉风险账。胶如何吸收 13.5 nm、能涂多厚，留给[下一课](/litho/euv-resist-absorption）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>寿命课的更换和破膜联锁，前提是膜在。无膜：双程吸收消失，瞬时光子变多，产能和随机项看起来变好；颗粒防护降为零，正面缺陷寿命由搬运和腔内产尘决定。早期 NXE 量产公开讨论过关键层无 pellicle、靠高频掩模检测和有限曝光次数的阶段。膜成熟后，无膜变成高功率过渡或特定层的例外，而不是默认。</p><p>缺口是把这条例外的风险写清楚，而不是重写 pellicle 光学。背面颗粒在无膜时仍然存在；正面再叠加硬缺陷，两面同时裸。</p><p><span class="marginnote">无膜不是「省一张膜的成本」。掩模检测、报废、机台开盖和良率尾部通常更贵。本课记账，不推荐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若必须无膜：收紧机械手与吸盘产尘、缩短掩模在机时间、提高光化或 succedent 检测频率、关键层用备份版。剂量可以因 \\(T^2\\) 消失而加快扫描，但随机效应若仍要高 \\(D\\)，速度优势被吃回。氢和 EUV 直接打在吸收体和帽上，表面化学与有膜时不同，碳生长和氢损伤地图要重资格认证。</p><p>与修复：无膜便于随时修，但缺陷发生率更高，修复队列变产能瓶颈。</p><h3 id="腔内产尘随功率不一定下降" tabindex="-1">腔内产尘随功率不一定下降 <a class="header-anchor" href="#腔内产尘随功率不一定下降" aria-label="Permalink to &quot;腔内产尘随功率不一定下降&quot;">​</a></h3><p>无膜常被当成高功率过渡：膜先扛不住。功率升高，台热、氢剥离和胶出气可能增加产尘，正面裸露的打印率上升。于是「为功率而摘膜」与「功率制造更多颗粒」打架。过渡策略必须同时收紧产尘和检测，不能只享受 \\(T^2=1\\)。</p>',12)),(a(),p(c,null,{default:i(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22%E6%97%A0%20pellicle%22%5D%20--%3E%20PHOT%5B%22%E5%A4%9A%E5%85%89%E5%AD%90%20%E6%97%A0%20T2%22%5D%0A%20%20NP%20--%3E%20DEF%5B%22%E6%AD%A3%E9%9D%A2%E9%A2%97%E7%B2%92%E5%8D%B3%E7%BC%BA%E9%99%B7%22%5D%0A%20%20DEF%20--%3E%20INSP%5B%22%E9%AB%98%E9%A2%91%E6%A3%80%E6%B5%8B%20%2F%20%E5%A4%87%E4%BB%BD%E7%89%88%22%5D%0A%20%20PHOT%20--%3E%20TPT%5B%22%E7%9C%8B%E4%BC%BC%E4%BA%A7%E8%83%BD%E5%8D%87%22%5D%0A%20%20INSP%20--%3E%20TPT%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离焦抑制没了：物镜把掩模面成像到硅片，颗粒在物面，尺寸超过打印阈值就成重复缺陷，整批晶圆同位置坏。这与膜上颗粒的模糊斑本质不同。腔内产尘来自台运动、氢致剥离、胶出气凝聚，无膜时这些源直达多层。功率越高，热梯度越大，产尘可能不降反升——与「无膜为了扛功率」的动机打架。</p><p><span class="marginnote">High-NA 打印更小缺陷，无膜窗口比 0.33 更窄。膜若仍不达标，矛盾会转到源功率与膜材料，而不是长期无膜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把胶的吸收系数和薄膜厚度写完，下一课才从记录介质吸收接着。不重写 DUV pellicle 标准。无膜过渡必须写检测频率和备份版，不能只写「源功率暂时更高」。出处：ASML pellicle 导入叙事；EUV 颗粒打印；寿命课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无膜换光子、付重复缺陷和检测税；不是稳态成本最优。</li><li>正面裸露改变帽层化学资格；背面风险并不消失。</li><li>下一课：硅片侧胶要吸收多少 13.5 nm 才能成像。</li><li>出处：ASML；pellicle 原理与寿命课。</li></ul>',7))])}const P=r(h,[["render",E]]);export{T as __pageData,P as default};
